    if(!points)return;const svg=$('hg-lines'),box=$('hg-board').getBoundingClientRect(),stage=svg.getBoundingClientRect();
    const tile=$('hg-board').firstElementChild.getBoundingClientRect(),style=getComputedStyle($('hg-board')),sx=(box.width+parseFloat(style.columnGap))/6,sy=(box.height+parseFloat(style.rowGap))/8;
