    if(busy){const visible=$('hg-board').querySelector('[data-r="'+r+'"][data-c="'+c+'"]');const uid=Number(visible?.dataset.uid);if(visible&&!visible.classList.contains('locked')&&!visible.classList.contains('vanish')&&!visible.classList.contains('burst')&&Number.isFinite(uid)){if(pendingPicks.length<2&&!pendingPicks.includes(uid))pendingPicks.push(uid);visible.classList.add('queued');}return;}
